  const AGIT_LINES = [
    { d: 1, tl: 'Me voy a quedar aquí, a esta distancia. Si quiere que me aleje un poco, dígamelo.', c: 'Me voy a quedar aquí, a esta distancia. Si quieres que me aleje un poco, dímelo.', en: 'I will stay right here, at this distance. If you want me to step back, tell me.', n: 'Respect personal space: two arm\'s lengths, step back if asked.' },
    { d: 3, tl: 'Hola. Soy el doctor ___, uno de los médicos de aquí. Quiero ayudarle y mantenerle a salvo.', c: 'Hola. Soy el doctor ___, uno de los médicos de aquí. Quiero ayudarte y mantenerte a salvo.', en: 'Hello. I am Dr. ___, one of the doctors here. I want to help you and keep you safe.', n: 'Establish verbal contact: one designated speaker. Say "la doctora" and "una de las médicas" as applicable.' },
    { d: 4, tl: 'Una cosa a la vez. Voy a ser breve, y se lo repito si hace falta.', c: 'Una cosa a la vez. Voy a ser breve, y te lo repito si hace falta.', en: 'One thing at a time. I will keep it short, and I will repeat it if needed.', n: 'Be concise; agitated patients process less.' },
    { d: 5, tl: '¿Qué necesita usted ahora mismo?', c: '¿Qué necesitas ahora mismo?', en: 'What do you need right now?', n: 'Identify wants and feelings.' },
    { d: 5, tl: 'Se nota que le frustra mucho haber esperado tanto tiempo.', c: 'Se nota que te frustra mucho haber esperado tanto tiempo.', en: 'It sounds like you are really frustrated that you have been waiting so long.' },
    { d: 6, tl: 'Lo que le escucho decir es: ___. ¿Es así?', c: 'Lo que te escucho decir es: ___. ¿Es así?', en: 'What I am hearing is ___. Did I get that right?', n: 'Listen closely and reflect back.' },
    { d: 7, tl: 'Tiene razón, la espera ha sido larga. Todos merecen respeto.', c: 'Tienes razón, la espera ha sido larga. Todos merecen respeto.', en: 'You are right, the wait has been long. Everyone deserves respect.', n: 'Agree with what is true and with principles, or agree to disagree.' },
    { d: 8, tl: 'Quiero ayudarle, y no puedo permitir que nadie salga lastimado. Si golpea a alguien, vamos a tener que intervenir para que todos estén seguros.', c: 'Quiero ayudarte, y no puedo permitir que nadie salga lastimado. Si golpeas a alguien, vamos a tener que intervenir para que todos estén seguros.', en: 'I want to help you, and I cannot let anyone get hurt. If you hit someone, we will have to step in to keep everyone safe.', n: 'Set clear limits: calm, factual, not punitive.' },
    { d: 9, tl: '¿Quiere algo que le ayude a sentirse más tranquilo? Tenemos una pastilla que puede tomar por la boca. ¿O prefiere primero tomar algo de beber?', c: '¿Quieres algo que te ayude a sentirte más tranquilo? Tenemos una pastilla que puedes tomar por la boca. ¿O prefieres primero tomar algo de beber?', en: 'Would you like something to help you feel calmer? We have a tablet you can take by mouth. Or would you like something to drink first?', n: 'Offer choices and optimism; offering oral medication as a real choice can prevent forced medication.' },
    { d: 9, tl: 'Esto no es un castigo. Cuando esté más en calma, va a ser más fácil hablar de lo que necesita.', c: 'Esto no es un castigo. Cuando estés más en calma, va a ser más fácil hablar de lo que necesitas.', en: 'This is not a punishment. Once you are calmer, it will be easier to talk about what you need.' },
    { d: 11, tl: 'Por su seguridad y la de los demás, tenemos que sujetarle por un momento. Le quitaremos las sujeciones en cuanto esté en calma. Vamos a estar con usted todo el tiempo.', c: 'Por tu seguridad y la de los demás, tenemos que sujetarte por un momento. Te quitaremos las sujeciones en cuanto estés en calma. Vamos a estar contigo todo el tiempo.', en: 'For your safety and others\', we need to restrain you briefly. It will be removed as soon as you are calm. We will stay with you the whole time.', n: 'If restraint is unavoidable: say what is happening, keep de-escalating, supine with head up, never prone, continuous observation.' },
    { d: 10, tl: 'Hace un rato, ¿qué le ayudó y qué no? ¿Qué le gustaría que hiciéramos la próxima vez, si vuelve a pasar?', c: 'Hace un rato, ¿qué te ayudó y qué no? ¿Qué te gustaría que hiciéramos la próxima vez, si vuelve a pasar?', en: 'Earlier, what helped and what did not? What would you like us to do next time if it happens again?', n: 'Debrief the patient and staff; record triggers and preferred interventions in an individualized plan.' }
  ];

